function cardStats(){return `<div class="grid stats"><div class="card"><span class="stat-label">俱乐部声望</span><div class="stat-value">1,240</div><span class="trend">↗ +86 本周</span></div><div class="card"><span class="stat-label">战队化学反应</span><div class="stat-value">68<span style="font-size:15px">%</span></div><span class="trend">↗ +4% 训练成果</span></div><div class="card"><span class="stat-label">全球排名</span><div class="stat-value"># 84</div><span class="trend">↗ 上升 12 位</span></div><div class="card"><span class="stat-label">本月现金流</span><div class="stat-value">+¥ 86K</div><span class="trend down">↘ -12% 较上月</span></div></div>`}
