function fixtureRows(){return realFixtures.map((x,i)=>'<div class="schedule-row fixture '+(x[5]==='已结束'?'finished':'')+'"><small>'+x[0]+'<br><em>'+x[3]+'</em></small><b>'+x[1]+' <span class="muted">vs</span> '+x[2]+'</b><span class="badge">'+x[4]+'</span><strong>'+x[6]+'</strong><button class="btn alt" onclick="fixtureDetail('+i+')">'+(x[5]==='已结束'?'战报':'准备')+'</button></div>').join('')}
eventCard=function(){return '<section class="card wide"><div class="card-head"><h2>全球 VCT 赛事日历</h2><span class="badge">'+realFixtures.length+' 场赛事</span></div><div class="event-meta"><span>CN：5 场</span><span>Pacific：2 场</span><span>EMEA：2 场</span><span>Americas：2 场</span></div>'+fixtureRows()+'</section>'};
function fixtureDetail(i){const x=realFixtures[i];toast(x[3]+' · '+x[1]+' vs '+x[2]+' · '+x[4]+' · '+(x[5]==='已结束'?'最终比分 '+x[6]:'比赛尚未开始'))}
const oldStartLive=startLiveMatch;startLiveMatch=function(){if(state.liveMatch){openLiveMatch();return}const x=realFixtures.find(v=>v[1]==='VOLT Academy'&&v[5]==='待进行')||realFixtures[2];state.currentFixture=x;oldStartLive()};
render();

