const MATCH_TACTICS={rush:{base:.015,eco:.05,counter:'slow'},default:{base:.03,eco:.02,counter:'rush'},slow:{base:.025,eco:-.01,counter:'default'}};
function matchNum(v,f=0){return Number.isFinite(Number(v))?Number(v):f}
function matchTeamPower(){const ids=state.signed||[];if(ids.length<5)return 35;let total=0,roleBonus=0;ids.slice(0,5).forEach(id=>{const p=players.find(x=>x[0]===id);const rating=matchNum(state.playerRatings?.[id],typeof playerRating==='function'?playerRating(p):60);const mood=matchNum(state.playerMood?.[id],70);total+=rating*.78+mood*.08;if(p?.[2]?.includes('IGL'))roleBonus+=2});return total/ids.length+matchNum(state.chemistry,50)*.06+matchNum(state.morale,70)*.045+roleBonus}
function matchOpponentPower(){const base=matchNum(typeof vctOpponentRating==='function'?vctOpponentRating():73,73);const division={网吧赛:-8,次级联赛:-4,挑战者联赛:0,'VCT CN':5}[state.division]||0;return base+division+matchNum(state.liveMatch?.opponentAdapt,0)}
function matchStartIfNeeded(){const m=state.liveMatch;if(!m)return; m.economy=matchNum(m.economy,8000);m.enemyEconomy=matchNum(m.enemyEconomy,8000);m.momentum=matchNum(m.momentum,0);m.streak=matchNum(m.streak,0);m.enemyStreak=matchNum(m.enemyStreak,0);m.lastTactic=m.lastTactic||'';m.opponentAdapt=matchNum(m.opponentAdapt,0);m.fatigue=matchNum(m.fatigue,0);m.tacticalStats=m.tacticalStats||{rush:0,default:0,slow:0}}
