const oldStartMatchV2=startLiveMatch;startLiveMatch=function(){oldStartMatchV2();if(state.liveMatch){matchStartIfNeeded();state.liveMatch.log.push('算法状态：经济、士气、地图风格与对手适应已启用');storySave();openLiveMatch()}};
