// Match center UX upgrade: live tournament board, round timeline and readable tactical controls.
const MATCH_TEAMS=['VOLT Academy','Nova Esports','Bilibili Gaming','EDward Gaming','Wolves Esports','DRG'];
function matchTeamStats(name){const w=name==='VOLT Academy'?(state.wins||0):([1,2,3,4,5][MATCH_TEAMS.indexOf(name)]||0);const l=name==='VOLT Academy'?(state.losses||0):([0,1,1,2,2][MATCH_TEAMS.indexOf(name)]||0);return {w,l,p:w*3};}
