openLiveMatch=function(){const m=state.liveMatch;if(!m)return openLiveMatchRich();document.querySelector('#live-match')?.remove();const x=document.createElement('div');x.id='live-match';x.className='inbox-layer match-layer';const rounds=(m.log||[]).filter(v=>v.includes('回合'));const paused=m.pausedUntil&&m.pausedUntil>Date.now();x.innerHTML=`<div class="match-modal"><div class="inbox-head"><div><span class="eyebrow">MATCH CENTER · LIVE</span><h2>VCT CN · ${m.map} · BO3</h2></div><button class="close-inbox" onclick="closeLiveMatch()">×</button></div><div class="series-head"><div><small>VOLT Academy</small><b>${m.seriesV}</b></div><strong>:</strong><div><small>Nova Esports</small><b>${m.seriesO}</b></div></div><div class="match-meta"><span>地图 ${m.mapIndex+1}/${m.maps.length}</span><span>本图 <b>${m.score}:${m.enemy}</b></span><span>${paused?'⏸ 暂停中':'● 比赛进行中'}</span><span>剩余暂停 <b>${m.timeouts??2}</b></span></div><div class="bp-summary"><b>地图 BP</b><span>禁用：${state.mapDraft?.bans?.join(' · ')||'系统'}</span><span>选择：${m.maps.join(' · ')}</span></div><h3>逐分战况 <small class="muted">${rounds.length} / ${m.score+m.enemy} 分</small></h3><div class="round-grid">${rounds.map((r,i)=>`<div class="round-card ${r.includes('VOLT')?'won':'lost'}"><b>R${i+1}</b><strong>${r.includes('VOLT')?'VOLT':'NOVA'}</strong><small>${r.match(/（(.*)）/)?.[1]||'回合结果'}</small></div>`).join('')||'<p class="muted">尚未开始，选择下方战术赢下第一分。</p>'}</div><div class="pause-bar"><button class="btn alt" onclick="useMatchTimeout()" ${paused?'disabled':''}>${paused?'暂停中':'叫暂停'}（${m.timeouts??2}）</button><button class="btn alt" onclick="requestTacticalPause()" ${paused?'disabled':''}>战术复盘 +8 准备度</button><span class="muted">暂停可在任何回合使用</span></div><div class="tactic-actions">${[['rush','快攻','高风险 · 枪法收益高'],['default','默认控图','均衡 · 稳定争夺资源'],['slow','慢打运营','低波动 · 协同收益高']].map(a=>`<button class="tactic-card" onclick="playLiveRound('${a[0]}')" ${paused?'disabled':''}><b>${a[1]}</b><small>${a[2]}</small></button>`).join('')}</div></div>`;document.body.appendChild(x)};
